from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(1,'grands-nombres','Les nombres jusqu’au million','1 · Nombres entiers et calculs',
'Classes · Rangs · Décompositions · Demi-droite',
['Lire, écrire et décomposer les nombres jusqu’à six chiffres.','Distinguer le chiffre des dizaines et le nombre de dizaines.','Comparer, encadrer et placer des nombres entiers.'],
['Numération jusqu’à 9 999 et tables d’addition.'],[
page(1,'Lire et décomposer les grands nombres',
bloc('definition',r'Dans un nombre entier, les chiffres sont groupés par classes de trois rangs : la classe des unités simples, puis la classe des mille. Le nombre $304\,065$ se lit « trois-cent-quatre-mille-soixante-cinq » : 304 dans la classe des mille, 065 dans la classe des unités.')+
tableau(['Classe','des mille','des unités simples'],[['Rangs','centaines, dizaines, unités','centaines, dizaines, unités'],[r'$304\,065$','3 0 4','0 6 5']]),
bloc('propriete',r'La valeur d’un chiffre dépend de sa position : dans $52\,700$, le chiffre 2 vaut $2\,000$. Dix unités font une dizaine, dix dizaines font une centaine, dix centaines font un millier : chaque rang vaut dix fois le rang placé à sa droite.'),
bloc('exemple',r'$304\,065=3\times100\,000+4\times1\,000+6\times10+5$. Les zéros gardent la place des rangs vides : sans eux, on lirait $3\,465$, un tout autre nombre.'),
bloc('savoirfaire',r'Dans $4\,627$, le chiffre des dizaines est 2. Le nombre de dizaines est 462, car $4\,627=462\times10+7$ : on compte toutes les dizaines contenues dans le nombre. Cette distinction sert pour les échanges : 462 carnets de dix timbres sont complets.','Chiffre ou nombre')),
page(2,'Comparer, encadrer et placer',
bloc('propriete',r'Pour comparer deux entiers : celui qui a le moins de chiffres est le plus petit ; à nombre de chiffres égal, on compare rang par rang en partant de la gauche. On écrit $9\,875<12\,034$ et $64\,350>64\,280$.'),
r'@FIG:cours-droite-mille@',
bloc('savoirfaire',r'Encadrer $45\,670$ entre deux dizaines de mille consécutives : $40\,000<45\,670<50\,000$. Intercaler un nombre entre $23\,500$ et $23\,600$ : par exemple $23\,540$. « Compris entre » se vérifie avec les deux symboles.','Encadrer et intercaler'),
bloc('attention',r'Sur une demi-droite graduée, lire d’abord la valeur d’un intervalle entre deux graduations. Un nombre n’est pas plus grand parce que son écriture semble plus longue à l’œil : comparer les rangs, pas la place occupée sur la page.'))
],[
E('Écrire en chiffres',r'Écrire en chiffres : « huit-mille-quarante » ; « vingt-trois-mille-quatre-cent-cinq » ; « six-cent-mille-neuf ».',r'On place chaque classe : $\res{8\,040}$, $\res{23\,405}$ et $\res{600\,009}$. Les rangs sans unités reçoivent un zéro.','Repérer la classe des mille dans le nom du nombre.','assert 8*1000+40==8040 and 23*1000+405==23405 and 600*1000+9==600009'),
E('Lire en classes',r'Écrire en lettres les nombres $86\,312$ et $450\,070$.',r'On lit la classe des mille puis celle des unités : $\res{\text{quatre-vingt-six-mille-trois-cent-douze}}$ et $\res{\text{quatre-cent-cinquante-mille-soixante-dix}}$.','Séparer les classes avant de lire.','assert 86*1000+312==86312 and 450*1000+70==450070'),
E('La valeur d’un chiffre',r'Dans $582\,741$, donner le chiffre des unités de mille, puis la valeur du chiffre 8.',r'Le chiffre des unités de mille est $\res2$. Le chiffre 8 occupe le rang des dizaines de mille : il vaut $\res{80\,000}$.','Associer chaque chiffre à son rang.','assert (582741//1000)%10==2 and (582741//10000)%10==8'),
E('Chiffre et nombre de dizaines',r'Pour le nombre $4\,627$, donner le chiffre des dizaines puis le nombre de dizaines.',r'Le chiffre des dizaines est $\res2$. Comme $4\,627=462\times10+7$, le nombre de dizaines est $\res{462}$.','Compter toutes les dizaines contenues.','assert (4627//10)%10==2 and 4627//10==462'),
E('Comparer deux nombres',r'Compléter par $<$ ou $>$ : $45\,806\ \ldots\ 45\,860$, puis $9\,875\ \ldots\ 12\,034$.',r'Les centaines sont égales, mais $0<6$ aux dizaines : $\res{45\,806<45\,860}$. Un nombre à quatre chiffres est plus petit qu’un nombre à cinq chiffres : $\res{9\,875<12\,034}$.','Comparer d’abord les longueurs, puis les rangs.','assert 45806<45860 and 9875<12034'),
E('Décomposer',r'Écrire la décomposition de $304\,065$ avec les valeurs de chaque chiffre.',r'$304\,065=\res{3\times100\,000+4\times1\,000+6\times10+5}$. Les rangs vides n’apparaissent pas dans la somme.','N’écrire que les rangs non nuls.','assert 3*100000+4*1000+6*10+5==304065'),
E('Recomposer',r'Quel nombre s’écrit $7\times10\,000+3\times100+9$ ? Et $5\times100\,000+2\times10$ ?',r'On place 7 aux dizaines de mille, 3 aux centaines, 9 aux unités : $\res{70\,309}$. Le second nombre est $\res{500\,020}$.','Placer chaque valeur à son rang, compléter par des zéros.','assert 7*10000+3*100+9==70309 and 5*100000+2*10==500020'),
E('Sur la demi-droite',r'Lire les nombres repérés par les points A, B et C.',r'Deux graduations marquées voisines diffèrent de $1\,000$ ; chaque petit intervalle vaut donc 500. On lit $\res{A(25\,000)}$, $\res{B(26\,500)}$ et $\res{C(27\,500)}$.','Chercher d’abord la valeur d’un intervalle.','assert 24000+2*500==25000 and 24000+5*500==26500 and 24000+7*500==27500',figure='num-8'),
E('Encadrer',r'Encadrer $45\,670$ entre deux dizaines de mille consécutives, puis $8\,294$ entre deux centaines consécutives.',r'$\res{40\,000<45\,670<50\,000}$ : les dizaines de mille voisines sont $40\,000$ et $50\,000$. Pour les centaines : $\res{8\,200<8\,294<8\,300}$.','Repérer le rang demandé avant d’encadrer.','assert 40000<45670<50000 and 8200<8294<8300'),
E('Ordonner',r'Ranger dans l’ordre croissant : $56\,400$ ; $9\,980$ ; $56\,040$ ; $100\,000$ ; $55\,999$.',r'Le nombre à quatre chiffres vient d’abord, celui à six chiffres en dernier. L’ordre est $\res{9\,980<55\,999<56\,040<56\,400<100\,000}$.','Grouper par nombre de chiffres puis comparer.','assert sorted([56400,9980,56040,100000,55999])==[9980,55999,56040,56400,100000]'),
E('Des fleuves à ranger',r'La Loire mesure $1\,006$ km, la Seine 775 km, la Garonne 647 km et le Rhône 812 km. Ranger ces fleuves du plus court au plus long. Lesquels mesurent moins de 800 km ?',r'L’ordre croissant des longueurs est $\res{647<775<812<1\,006}$ : Garonne, Seine, Rhône, Loire. La Garonne et la Seine mesurent moins de 800 km, car $\res{647<800}$ et $\res{775<800}$.','Comparer les nombres avant de conclure sur les fleuves.','assert sorted([1006,775,647,812])==[647,775,812,1006] and [d for d in [1006,775,647,812] if d<800]==[775,647]'),
E('Des carnets de timbres',r'Une collection compte $3\,240$ timbres, rangés par carnets de 10. Combien de carnets complets obtient-on ? Même question pour $5\,278$ timbres, puis donner le nombre de timbres restants.',r'$3\,240=324\times10$ : on remplit $\res{324}$ carnets, sans reste. $5\,278=527\times10+8$ : on remplit $\res{527}$ carnets et il reste $\res8$ timbres. Le nombre de carnets complets est le nombre de dizaines.','Relier carnets de dix et nombre de dizaines.','assert divmod(3240,10)==(324,0) and divmod(5278,10)==(527,8)'),
E('Un nombre à inventer',r'Trouver un nombre compris entre $45\,300$ et $45\,400$ dont le chiffre des dizaines est 7. Combien y a-t-il de possibilités ?',r'Le nombre s’écrit $45\,37\square$ : par exemple $\res{45\,370}$. Le chiffre des unités est libre : il y a $\res{10}$ possibilités, de $45\,370$ à $45\,379$.','Fixer les rangs imposés, libérer les autres.','assert 45300<45370<45400 and (45370//10)%10==7 and len([a for a in range(45300,45400) if (a//10)%10==7])==10'),
E('Avec cinq cartes',r'Avec les cartes 7, 0, 3, 9 et 1 utilisées chacune une fois, former le plus grand nombre possible, puis le plus petit nombre à cinq chiffres.',r'Pour le plus grand, ranger les cartes en ordre décroissant : $\res{97\,310}$. Pour le plus petit, commencer par le plus petit chiffre non nul puis ranger le reste en ordre croissant : $\res{10\,379}$. Un nombre à cinq chiffres ne commence pas par 0.','Choisir d’abord le chiffre de gauche.',"assert ''.join(sorted('70391',reverse=True))=='97310' and ''.join(sorted('70391'))=='01379' and 10379==int('1'+'0379')"),
E('Trois communes',r'Trois communes comptent $45\,806$, $45\,860$ et $9\,980$ habitants. Ranger les populations dans l’ordre décroissant, encadrer la plus grande entre deux dizaines de mille consécutives et donner son chiffre des centaines.',r'L’ordre décroissant est $\res{45\,860>45\,806>9\,980}$. La plus grande population vérifie $\res{40\,000<45\,860<50\,000}$. Son chiffre des centaines est $\res8$.','Traiter chaque question avec le même nombre bien identifié.','assert sorted([45806,45860,9980],reverse=True)==[45860,45806,9980] and 40000<45860<50000 and (45860//100)%10==8')
],reperes=['Classes, rangs et décompositions','Chiffre et nombre d’unités','Comparer, encadrer, intercaler','Demi-droite graduée et problèmes'],deco='calcul')

chapitre(2,'addition-soustraction','Additionner et soustraire','1 · Nombres entiers et calculs',
'Sommes · Différences · Estimation · Schémas en barres',
['Poser et effectuer additions et soustractions d’entiers.','Estimer un résultat avant de calculer.','Résoudre des problèmes en une, deux ou trois étapes.'],
['Numération jusqu’au million et tables d’addition.'],[
page(1,'Calculer des sommes et des différences',
bloc('definition',r'Le résultat d’une addition est une somme ; les nombres ajoutés sont les termes. Le résultat d’une soustraction est une différence. Dans une addition, l’ordre des termes ne change pas la somme : $47+385=385+47$.'),
bloc('savoirfaire',r'Pour poser une opération, aligner les chiffres rang par rang : unités sous unités, dizaines sous dizaines. Dans $5\,204-1\,368$, un rang trop petit s’échange : une dizaine contre dix unités. On obtient $3\,836$.','Poser proprement'),
bloc('exemple',r'$6\,478+525$ : $8+5=13$, on écrit 3 et on retient une dizaine. En poursuivant rang par rang, la somme est $7\,003$. Contrôle : $7\,003-525=6\,478$.'),
bloc('savoirfaire',r'Avant de calculer, arrondir chaque terme : $6\,478+525$ est proche de $6\,500+500=7\,000$. Une réponse éloignée de l’estimation doit être refaite. Pour ajouter 9, 19 ou 29 de tête : ajouter 10, 20 ou 30, puis retirer 1.','Estimer puis contrôler')),
page(2,'Résoudre un problème pas à pas',
bloc('propriete',r'Résoudre un problème se fait en quatre étapes : comprendre l’histoire du problème, modéliser en choisissant les opérations, calculer, puis répondre par une phrase et vérifier que la réponse est vraisemblable.'),
r'@FIG:cours-barres@',
bloc('exemple',r'« Une école compte 258 élèves ; 136 sont des filles. » Le schéma en barres montre un tout (258) et deux parties. Le nombre de garçons est la partie manquante : $258-136=122$.'),
bloc('attention',r'Un mot ne décide pas de l’opération. « Léa a 12 billes de plus que Tom » peut demander une soustraction, si on connaît le nombre de billes de Léa et qu’on cherche celui de Tom. Relire l’histoire entière avant de calculer.'))
],[
E('Deux sommes posées',r'Poser et calculer $6\,478+525$ et $38\,467+4\,850$.',r'En alignant les rangs : $6\,478+525=\res{7\,003}$ et $38\,467+4\,850=\res{43\,317}$. L’estimation $38\,000+5\,000=43\,000$ confirme l’ordre de grandeur.','Aligner les unités sous les unités.','assert 6478+525==7003 and 38467+4850==43317'),
E('Deux différences posées',r'Poser et calculer $5\,204-1\,368$ et $70\,000-2\,460$.',r'$5\,204-1\,368=\res{3\,836}$ ; contrôle : $3\,836+1\,368=5\,204$. Avec les zéros : $70\,000-2\,460=\res{67\,540}$.','Vérifier chaque différence par une addition.','assert 5204-1368==3836 and 3836+1368==5204 and 70000-2460==67540'),
E('Compléments utiles',r'Compléter : $64+\ldots=100$, puis $380+\ldots=1\,000$.',r'$64+36=100$, donc le complément est $\res{36}$. $380+620=1\,000$, donc le complément est $\res{620}$.','Chercher ce qui manque pour atteindre le repère.','assert 64+36==100 and 380+620==1000'),
E('Ajouter 9, 19, 29 de tête',r'Calculer mentalement $457+9$, $457+19$ et $262+29$.',r'On ajoute la dizaine entière puis on retire 1 : $457+10-1=\res{466}$ ; $457+20-1=\res{476}$ ; $262+30-1=\res{291}$.','Passer par la dizaine supérieure.','assert 457+9==466 and 457+19==476 and 262+29==291'),
E('Estimer avant de calculer',r'Sans poser l’opération, choisir le résultat de $4\,980+3\,120$ parmi : $810$ ; $8\,100$ ; $81\,000$. Justifier.',r'$4\,980$ est proche de $5\,000$ et $3\,120$ de $3\,000$ : la somme est proche de $8\,000$. Le seul résultat vraisemblable est $\res{8\,100}$.','Arrondir chaque terme au millier.','assert 4980+3120==8100'),
E('Regrouper pour aller vite',r'Calculer $254+378+46$ en regroupant deux termes bien choisis.',r'On regroupe $254+46=300$, puis $300+378=\res{678}$. L’ordre des termes d’une somme peut être changé.','Chercher deux termes dont la somme est ronde.','assert 254+46==300 and 254+378+46==678'),
E('Une soustraction à trous',r'Compléter : $\ldots-247=385$, puis $902-\ldots=345$.',r'Le premier nombre vaut $385+247=\res{632}$. Pour le second : $902-345=\res{557}$. Contrôles : $632-247=385$ et $902-557=345$.','Utiliser l’opération qui défait l’autre.','assert 632-247==385 and 902-557==345'),
E('Le bon panneau',r'Entre Villeneuve et Beaupré, un automobiliste lit « Beaupré 68 km » puis, plus loin, « Beaupré 29 km ». Quelle distance a-t-il parcourue entre les deux panneaux ?',r'La distance restante a diminué de $68-29=\res{39}$ km. Le mot « plus loin » n’indique pas une addition : c’est l’écart entre deux restes.','Comparer les deux distances restantes.','assert 68-29==39'),
E('Avec un schéma en barres',r'Un théâtre propose 850 places. 512 billets sont vendus le samedi et 218 le dimanche. Représenter la situation puis dire combien de places restent libres.',r'Les deux parties vendues totalisent $512+218=730$ billets. La partie manquante du schéma vaut $850-730=\res{120}$ places libres. Contrôle : $730+120=850$.','Dessiner le tout et les parties connues.','assert 512+218==730 and 850-730==120',figure='barres-9'),
E('Le compte est-il bon ?',r'Issa calcule $4\,003-1\,587=3\,584$. Vérifier avec une addition, corriger s’il le faut.',r'$3\,584+1\,587=5\,171$, qui n’est pas $4\,003$ : le résultat est faux. Le bon calcul donne $4\,003-1\,587=\res{2\,416}$ ; contrôle : $2\,416+1\,587=4\,003$.','Toujours contrôler une différence par la somme.','assert 3584+1587==5171 and 4003-1587==2416 and 2416+1587==4003'),
E('La bibliothèque',r'Une bibliothèque possède $12\,540$ livres. Elle en prête $3\,275$, puis reçoit un don de $1\,860$ livres. Combien de livres sont présents sur les étagères ?',r'Après les prêts, il reste $12\,540-3\,275=9\,265$ livres. Après le don, les étagères portent $9\,265+1\,860=\res{11\,125}$ livres. L’estimation $12\,500-3\,300+1\,900\approx11\,100$ confirme la réponse.','Suivre l’histoire étape par étape.','assert 12540-3275==9265 and 9265+1860==11125'),
E('Qui a le plus ?',r'Nina a 325 cartes. Elle a 68 cartes de plus que Marco. Combien Marco a-t-il de cartes ? Combien de cartes ont-ils ensemble ?',r'Nina a plus de cartes : Marco en a $325-68=\res{257}$. Ensemble, ils ont $325+257=\res{582}$ cartes. Le mot « plus » décrivait la comparaison, pas l’opération.','Repérer qui possède le plus avant de calculer.','assert 325-68==257 and 325+257==582',figure='barres-12'),
E('La cagnotte de la classe',r'Une classe doit réunir $1\,500$ euros pour un séjour. La vente de gâteaux rapporte 480 euros, la tombola 655 euros. Combien manque-t-il encore ?',r'Les recettes totalisent $480+655=1\,135$ euros. Il manque $1\,500-1\,135=\res{365}$ euros. Contrôle : $1\,135+365=1\,500$.','Calculer d’abord ce qui est déjà réuni.','assert 480+655==1135 and 1500-1135==365'),
E('Trois étapes de course',r'Un rallye de $2\,000$ km se court en trois étapes. La première mesure 712 km, la deuxième 56 km de moins que la première. Quelle est la longueur de la troisième étape ?',r'La deuxième étape mesure $712-56=656$ km. Les deux premières totalisent $712+656=1\,368$ km. La troisième mesure $2\,000-1\,368=\res{632}$ km. Contrôle : $712+656+632=2\,000$.','Déduire chaque donnée manquante dans l’ordre.','assert 712-56==656 and 712+656==1368 and 2000-1368==632 and 712+656+632==2000'),
E('Le vrai du faux',r'Chloé affirme : « Pour calculer $757-398$, je calcule $759-400$, c’est plus simple. » A-t-elle raison ? Expliquer puis donner le résultat.',r'Ajouter 2 aux deux nombres ne change pas leur écart : $\res{\text{elle a raison}}$. $759-400=\res{359}$, donc $757-398=359$. Sur une droite, les deux nombres ont glissé ensemble de 2.','Conserver l’écart en déplaçant les deux nombres.','assert 757-398==359 and 759-400==359')
],reperes=['Techniques posées et contrôles','Calcul mental et estimations','Problèmes parties-tout','Comparaisons et étapes multiples'],deco='calcul')

chapitre(3,'multiplication','Multiplier des entiers','1 · Nombres entiers et calculs',
'Produits · Technique posée · Calcul réfléchi',
['Poser et effectuer une multiplication à un ou deux chiffres.','Multiplier par 10, 100, 1 000 et par des dizaines entières.','Utiliser des produits pour comparer et dénombrer.'],
['Tables de multiplication et addition posée.'],[
page(1,'Comprendre et poser une multiplication',
bloc('definition',r'Le résultat d’une multiplication est un produit ; les nombres multipliés sont les facteurs. L’ordre des facteurs ne change pas le produit : $8\times26=26\times8$. Un produit remplace une addition de termes identiques : $26+26+26=3\times26$.'),
r'@FIG:cours-produit@',
bloc('propriete',r'Multiplier par 10 décale chaque chiffre d’un rang vers la gauche : $47\times10=470$. De même, $47\times100=4\,700$ et $47\times1\,000=47\,000$ : les unités deviennent des dizaines, des centaines, des milliers.'),
bloc('savoirfaire',r'Pour $347\times26$, on calcule $347\times6=2\,082$, puis $347\times20=6\,940$, et on additionne : $9\,022$. La seconde ligne se termine par le zéro de $\times20$.','Poser avec deux lignes')),
page(2,'Calculer de façon réfléchie',
bloc('propriete',r'Un facteur peut être décomposé : $23\times12=23\times10+23\times2=230+46=276$. Distribuer la multiplication sur une somme donne des étapes simples à calculer de tête.'),
bloc('exemple',r'Multiplier par 4, c’est doubler deux fois : $35\times4=70\times2=140$. Multiplier par 8, c’est doubler trois fois. Multiplier par 5, c’est multiplier par 10 puis prendre la moitié : $68\times5=680:2=340$.'),
bloc('savoirfaire',r'Pour $6\times300$, calculer $6\times3=18$ puis accrocher les deux zéros : $1\,800$. Pour $40\times70$, $4\times7=28$ puis deux zéros : $2\,800$.','Multiplier des dizaines et des centaines'),
bloc('attention',r'« 3 fois plus » signifie que l’on multiplie par 3. Avant de calculer un produit, estimer : $347\times26$ est proche de $350\times25$, soit environ $8\,750$. Un résultat dix fois trop grand signale souvent un zéro oublié.'))
],[
E('Des tables bien connues',r'Compléter : $7\times8=\ldots$ ; $9\times6=\ldots$ ; $\ldots\times6=48$.',r'$7\times8=\res{56}$ et $9\times6=\res{54}$. Pour la dernière égalité, $8\times6=48$ : le facteur manquant est $\res8$.','Réciter la table du facteur connu.','assert 7*8==56 and 9*6==54 and 8*6==48'),
E('Une addition qui se répète',r'Écrire $45+45+45+45$ sous la forme d’un produit, puis calculer.',r'Quatre termes égaux à 45 : $4\times45$. On double deux fois : $45\times2=90$ puis $90\times2=\res{180}$.','Compter les termes identiques.','assert 45+45+45+45==4*45==180'),
E('Multiplier par 10, 100, 1 000',r'Calculer $47\times10$, $358\times100$ et $6\times1\,000$.',r'Chaque chiffre monte d’un, deux ou trois rangs : $\res{470}$, $\res{35\,800}$ et $\res{6\,000}$.','Décaler les rangs, compléter par des zéros.','assert 47*10==470 and 358*100==35800 and 6*1000==6000'),
E('Un produit posé',r'Poser et calculer $486\times7$.',r'$6\times7=42$ : on pose 2, retenue 4. En poursuivant, $486\times7=\res{3\,402}$. Estimation : $500\times7=3\,500$, le résultat est vraisemblable.','Multiplier rang par rang avec les retenues.','assert 486*7==3402'),
E('Multiplier par 5',r'Calculer de tête $68\times5$ et $240\times5$.',r'Multiplier par 10 puis prendre la moitié : $680:2=\res{340}$ et $2\,400:2=\res{1\,200}$.','Passer par la multiplication par 10.','assert 68*5==340 and 240*5==1200'),
E('Deux chiffres au multiplicateur',r'Poser et calculer $347\times26$.',r'$347\times6=2\,082$ et $347\times20=6\,940$. La somme donne $347\times26=\res{9\,022}$. L’estimation $350\times25=8\,750$ confirme l’ordre de grandeur.','Séparer les unités et les dizaines du multiplicateur.','assert 347*6==2082 and 347*20==6940 and 347*26==9022'),
E('Décomposer un facteur',r'Calculer $23\times12$ sans poser l’opération, en décomposant 12.',r'$23\times12=23\times10+23\times2=230+46=\res{276}$. La multiplication se distribue sur la somme $10+2$.','Découper le facteur en dizaines et unités.','assert 23*10+23*2==276 and 23*12==276'),
E('Des dizaines entre elles',r'Calculer $40\times70$, $300\times6$ et $50\times80$.',r'$4\times7=28$ puis deux zéros : $\res{2\,800}$. $3\times6=18$ puis deux zéros : $\res{1\,800}$. $5\times8=40$ puis deux zéros : $\res{4\,000}$ ; le zéro de 40 s’ajoute aux deux autres.','Multiplier les chiffres puis compter les zéros.','assert 40*70==2800 and 300*6==1800 and 50*80==4000'),
E('Le facteur caché',r'Compléter : $25\times\ldots=200$, puis $\ldots\times30=270$.',r'$25\times8=200$ : le facteur est $\res8$. $9\times30=270$ : le facteur est $\res9$.','S’appuyer sur une table proche.','assert 25*8==200 and 9*30==270'),
E('Trois fois plus',r'Un stade accueille $8\,250$ spectateurs le samedi. Le dimanche, il en accueille trois fois plus. Combien de spectateurs viennent le dimanche ?',r'« Trois fois plus » signifie multiplier par 3 : $8\,250\times3=\res{24\,750}$ spectateurs. Une addition de $8\,250$ ne suffirait pas : elle ne donnerait que « $8\,250$ de plus ».','Traduire « fois plus » par une multiplication.','assert 8250*3==24750'),
E('La commande de la cantine',r'La cantine commande 26 cagettes de 145 pommes et 18 cagettes de 230 poires. Combien de fruits reçoit-elle en tout ?',r'Pommes : $145\times26=3\,770$. Poires : $230\times18=4\,140$. Total : $3\,770+4\,140=\res{7\,910}$ fruits. Estimation : $150\times26+230\times20\approx8\,500$, proche du résultat.','Calculer chaque produit avant la somme.','assert 145*26==3770 and 230*18==4140 and 3770+4140==7910'),
E('La salle de spectacle',r'Une salle compte 32 rangées de 28 fauteuils. Pour un concert, 850 billets sont vendus. Reste-t-il des places libres ?',r'La salle offre $32\times28=896$ places. Comme $896>850$, il reste $896-850=\res{46}$ places libres.','Comparer la capacité au nombre de billets.','assert 32*28==896 and 896-850==46'),
E('Des menus à composer',r'Un restaurant propose 3 entrées et 4 plats. Combien de menus « entrée puis plat » différents peut-on composer ? Avec 2 desserts en plus, combien de menus complets ?',r'Chaque entrée se combine avec chaque plat : $3\times4=\res{12}$ menus. Chaque menu accepte 2 desserts : $12\times2=\res{24}$ menus complets. Un arbre de choix retrouve ce dénombrement.','Multiplier le nombre de choix de chaque étape.','assert 3*4==12 and 12*2==24'),
E('L’économie de Salomé',r'Salomé met de côté 35 euros par mois pendant un an. Son frère met 3 euros par semaine pendant 52 semaines. Qui économise le plus ?',r'Salomé : $35\times12=420$ euros. Son frère : $3\times52=156$ euros. $420>156$ : $\res{\text{Salomé économise le plus}}$, avec $420-156=\res{264}$ euros d’avance.','Ramener les deux économies à l’année.','assert 35*12==420 and 3*52==156 and 420-156==264'),
E('Le piège du double',r'Maël affirme : « $25\times16$, c’est pareil que $50\times8$. » A-t-il raison ? Expliquer, puis donner le produit.',r'Doubler un facteur et prendre la moitié de l’autre conserve le produit : $\res{\text{il a raison}}$. $50\times8=\res{400}$, donc $25\times16=400$. On peut continuer : $100\times4=400$.','Compenser : un facteur double, l’autre est divisé par deux.','assert 25*16==400 and 50*8==400 and 100*4==400')
],reperes=['Sens du produit et tables','Technique posée et estimation','Multiplier par 10, 100 et des dizaines','Problèmes multiplicatifs et dénombrement'],deco='calcul')
